import express from 'express';
import { z } from 'zod';

class AppError extends Error {
  constructor(status, kode, pesan, detail) {
    super(pesan);
    Object.assign(this, { status, kode, detail });
  }
}
const stok = { 1: 1 };
const app = express();
app.use(express.json());
app.post('/produk/:id/beli', (req, res) => {
  const { jumlah } = z.object({ jumlah: z.number().int().positive() }).parse(req.body);
  const id = req.params.id;
  if (!(id in stok)) throw new AppError(404, 'PRODUK_TIDAK_ADA', `Produk ${id} tidak ada`);
  if (stok[id] < jumlah) throw new AppError(409, 'STOK_KURANG', `Stok tinggal ${stok[id]}`);
  stok[id] -= jumlah;
  res.json({ data: { id: Number(id), sisa: stok[id] } });
});
app.use((err, req, res, next) => {
  if (err instanceof z.ZodError) {
    err = new AppError(400, 'VALIDASI_GAGAL', 'Data tidak valid', err.issues.map((i) => i.path.join('.')));
  } else if (!(err instanceof AppError)) {
    err = new AppError(500, 'KESALAHAN_SERVER', 'Terjadi kesalahan di server');
  }
  res.status(err.status).json({ error: { kode: err.kode, pesan: err.message, detail: err.detail ?? [] } });
});
const server = app.listen(3000);

const beli = async (id, body) => {
  const r = await fetch(`http://localhost:3000/produk/${id}/beli`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  const isi = await r.json();
  console.log(r.status, isi.data ?? isi.error.kode);
};
await beli(1, { jumlah: 1 });
await beli(1, { jumlah: 1 });
await beli(7, { jumlah: 1 });
await beli(1, { jumlah: 'dua' });
server.close();

