cards.solution:
function jawabError(err) {
  if (err.kode) return { status: err.status, isi: { error: { kode: err.kode, pesan: err.message } } };
  return { status: 500, isi: { error: { kode: 'KESALAHAN_SERVER', pesan: 'Terjadi kesalahan' } } };
}
console.log(jawabError(new Error('x')));

